#include "stdafx.h"#include "HcdElementBase.h"#include <rsuStr.h>struct SAND_P{#include "PrivateVars/AND.h"};class KAND : public KHcdElementBase  , protected SAND_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual int SetProjectValue( LPCSTR pszName, LPCSTR pszValue );  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _AND("AND", KAND::Create);IHcdElement *KAND::Create(){  return new KAND;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KAND, 17 )void KAND::InitParm(){#include "PrivateVars/AND.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KAND::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;  tBool *pIn = &INL0;  for( int i=0; i<8; ++i )    pIn[i] = 1;}int KAND::SetProjectValue( LPCSTR pszName, LPCSTR pszValue ){  int r = -1;  r = __super::SetProjectValue( pszName, pszValue );  if( !_Kstrnicmp(pszName,"Invert Input ",13) )  {    tBool *pInvert = &II1;    tBool *pIn = &INL0;    int i = atoi(pszName+13) - 1;    if ( pInvert[i] )      pIn[i] = 0;  }  return r;}void KAND::StepCalc( SStepCalcParams &params ){  tBool *pInvert = &II1;  tBool *pIn = &INL0;  if( pInvert[0] )    OUTR0 = pIn[0] ? 0 : 1;  else    OUTR0 = pIn[0] ? 1 : 0;  for( int i=1; i<8; ++i )  {    if( pInvert[i] )      OUTR0 = (pIn[i] ? 0 : 1) & OUTR0;    else      OUTR0 = (pIn[i] ? 1 : 0) & OUTR0;    if( !OUTR0 )      break;  }}